```c
#include <atomic>
#include <cstdint>

struct Node { 
    int val; 
    Node* next; 
};

// Tagged pointer to solve ABA problem
struct TaggedPointer {
    Node* ptr;
    uint64_t tag;

    TaggedPointer() : ptr(nullptr), tag(0) {}
    TaggedPointer(Node* p, uint64_t t) : ptr(p), tag(t) {}
};

std::atomic<TaggedPointer> top;

void push(int v) {
    TaggedPointer old_top = top.load();
    Node* n = new Node{v, old_top.ptr};
    TaggedPointer new_top(n, old_top.tag + 1);
    while (!top.compare_exchange_weak(old_top, new_top)) {
        n->next = old_top.ptr;
        new_top.ptr = n;
        new_top.tag = old_top.tag + 1;
    }
}

int pop() {
    TaggedPointer old_top = top.load();
    while (old_top.ptr) {
        TaggedPointer new_top(old_top.ptr->next, old_top.tag + 1);
        if (top.compare_exchange_weak(old_top, new_top)) {
            int val = old_top.ptr->val;
            delete old_top.ptr;
            return val;
        }
    }
    return -1;
}
```

This fix uses a tag to distinguish between different versions of the same pointer, preventing the ABA problem. Each time a node is pushed or popped, the tag is incremented, ensuring that even if the same memory address is reused, the operation will fail if the tag doesn't match.

